import React, { useState, useEffect } from 'react';
import NetflixProjectRow from '../components/NetflixProjectRow';
import ContactModal from '../components/ContactModal';
import ProjectModal from '../components/ProjectModal';
import { useFilters } from '../contexts/FilterContext';
import type { Project } from '../types';
import './HomePage.css';

const HomePage: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  
  const { 
    filters, 
    filteredProjects, 
    hasActiveFilters, 
    setProjects: setFilterProjects 
  } = useFilters();

  // Simple data loading without complex hooks
  useEffect(() => {
    const loadProjects = async () => {
      try {
        setLoading(true);
        const response = await fetch(`${import.meta.env.BASE_URL}data/projects.json`);
        if (response.ok) {
          const data = await response.json();
          const transformedProjects = data.projects.map((project: any) => ({
            ...project,
            createdAt: new Date(project.createdAt),
            updatedAt: new Date(project.updatedAt)
          }));
          setProjects(transformedProjects);
          setFilterProjects(transformedProjects); // Initialize filter context
        }
      } catch (error) {
        console.error('Error loading projects:', error);
      } finally {
        setLoading(false);
      }
    };

    loadProjects();
  }, [setFilterProjects]);

  // Event handlers for modal interactions
  const handleProjectSelect = (project: Project) => {
    setSelectedProject(project);
  };

  const handleCloseModal = () => {
    setSelectedProject(null);
  };

  const handleRelatedProjectSelect = (project: Project) => {
    setSelectedProject(project);
  };

  // Get related projects (same category, excluding current project)
  const getRelatedProjects = (currentProject: Project): Project[] => {
    return projects
      .filter(project => 
        project.id !== currentProject.id && 
        project.category.id === currentProject.category.id
      )
      .slice(0, 3);
  };

  // Show loading state for initial load
  if (loading && projects.length === 0) {
    return (
      <div className="home-page">
        <section className="home-page__content">
          <div className="skeleton-grid">
            {Array.from({ length: 8 }, (_, index) => (
              <div key={index} className="project-preview" style={{ 
                background: 'rgba(255, 255, 255, 0.05)', 
                padding: '1.5rem', 
                borderRadius: '8px',
                animation: 'pulse 2s infinite'
              }}>
                <div style={{ height: '1.5rem', background: 'rgba(255, 255, 255, 0.1)', borderRadius: '4px', marginBottom: '0.5rem' }}></div>
                <div style={{ height: '1rem', background: 'rgba(255, 255, 255, 0.1)', borderRadius: '4px', marginBottom: '1rem' }}></div>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                  <div style={{ height: '1.5rem', width: '60px', background: 'rgba(255, 255, 255, 0.1)', borderRadius: '12px' }}></div>
                  <div style={{ height: '1.5rem', width: '80px', background: 'rgba(255, 255, 255, 0.1)', borderRadius: '12px' }}></div>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    );
  }

  // Get featured projects for the main row - use filtered projects if searching
  const projectsToShow = hasActiveFilters ? filteredProjects : projects;
  const featuredProjects = projectsToShow.filter(project => project.featured).slice(0, 5);
  const allProjectsForRow = projectsToShow.slice(0, 5);

  return (
    <div className="home-page">
      {/* Show search results prominently when searching */}
      {hasActiveFilters ? (
        <section 
          className="home-page__search-results"
          role="main"
          aria-label="Search results"
        >
          {/* Show filtered results in Netflix-style row */}
          {filteredProjects.length > 0 ? (
            <NetflixProjectRow
              title={`Search Results (${filteredProjects.length} project${filteredProjects.length !== 1 ? 's' : ''})`}
              projects={filteredProjects}
              onProjectSelect={handleProjectSelect}
            />
          ) : (
            <div className="home-page__no-results">
              <h2>No projects match your search</h2>
              <p>We couldn't find any projects matching "{filters.searchQuery}". Try different keywords or browse all projects below.</p>
            </div>
          )}
        </section>
      ) : (
        /* Netflix-style Project Rows - Show when not searching */
        <section className="home-page__netflix-section">
          {featuredProjects.length > 0 && (
            <NetflixProjectRow
              title="New on Craig's Portfolio"
              projects={featuredProjects}
              onProjectSelect={handleProjectSelect}
            />
          )}
          
          <NetflixProjectRow
            title="Projects we think you'll love"
            projects={allProjectsForRow}
            onProjectSelect={handleProjectSelect}
          />
          
          {/* Contact Section */}
          <NetflixProjectRow
            title="Because you liked Craig's Projects"
            projects={[]}
            onProjectSelect={() => {}}
            showContactCard={true}
            onContactClick={() => setIsContactModalOpen(true)}
          />
        </section>
      )}

      {selectedProject && (
        <ProjectModal
          project={selectedProject}
          onClose={handleCloseModal}
          relatedProjects={getRelatedProjects(selectedProject)}
          onProjectSelect={handleRelatedProjectSelect}
        />
      )}

      <ContactModal
        isOpen={isContactModalOpen}
        onClose={() => setIsContactModalOpen(false)}
      />
    </div>
  );
};

export default HomePage;