import React, { useRef, useState } from 'react';
import type { Project } from '../types';
import LazyImage from './LazyImage';
import ContactCard from './ContactCard';
import { announceToScreenReader } from '../utils/focusManagement';
import { getAutoResizedThumbnails } from '../utils/imageAutoResize';
import './NetflixProjectRow.css';

interface NetflixProjectRowProps {
  title: string;
  projects: Project[];
  onProjectSelect: (project: Project) => void;
  showContactCard?: boolean;
  onContactClick?: () => void;
}

const NetflixProjectRow: React.FC<NetflixProjectRowProps> = ({
  title,
  projects,
  onProjectSelect,
  showContactCard = false,
  onContactClick
}) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const checkScrollButtons = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
      setCanScrollLeft(scrollLeft > 0);
      setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 1);
    }
  };

  const scroll = (direction: 'left' | 'right') => {
    if (scrollContainerRef.current) {
      const scrollAmount = scrollContainerRef.current.clientWidth * 0.8;
      const newScrollLeft = direction === 'left' 
        ? scrollContainerRef.current.scrollLeft - scrollAmount
        : scrollContainerRef.current.scrollLeft + scrollAmount;

      scrollContainerRef.current.scrollTo({
        left: newScrollLeft,
        behavior: 'smooth'
      });

      setTimeout(checkScrollButtons, 300);
    }
  };

  const handleProjectClick = (project: Project) => {
    onProjectSelect(project);
    announceToScreenReader(`Opening ${project.title} project details`, 'assertive');
  };

  const handleKeyDown = (event: React.KeyboardEvent, project: Project) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleProjectClick(project);
    }
  };

  React.useEffect(() => {
    checkScrollButtons();
    
    const handleResize = () => checkScrollButtons();
    window.addEventListener('resize', handleResize);
    
    return () => window.removeEventListener('resize', handleResize);
  }, [projects]);



  if (projects.length === 0 && !showContactCard) return null;

  return (
    <div className="netflix-row">
      <h2 className="netflix-row__title">{title}</h2>
      
      <div className="netflix-row__container">
        {canScrollLeft && (
          <button
            className="netflix-row__scroll-btn netflix-row__scroll-btn--left"
            onClick={() => scroll('left')}
            aria-label="Scroll left"
          >
            <svg viewBox="0 0 24 24" fill="currentColor">
              <path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/>
            </svg>
          </button>
        )}

        <div
          ref={scrollContainerRef}
          className="netflix-row__slider"
          onScroll={checkScrollButtons}
        >
          {projects.map((project) => {
            const resizedThumbnails = getAutoResizedThumbnails(project.thumbnailUrl);
            
            return (
              <div
                key={project.id}
                className="netflix-row__item"
                onClick={() => handleProjectClick(project)}
                onKeyDown={(e) => handleKeyDown(e, project)}
                tabIndex={0}
                role="button"
                aria-label={`View ${project.title} project details`}
              >
                <div className="netflix-row__card">
                  <div className="netflix-row__image-container">
                    <LazyImage
                      src={resizedThumbnails.medium}
                      alt={project.title}
                      className="netflix-row__image"
                      sizes="(max-width: 768px) 280px, (max-width: 1024px) 320px, 400px"
                      aspectRatio="16 / 9"
                    />
                  
                    <div className="netflix-row__overlay">
                      <div className="netflix-row__content">
                        <h3 className="netflix-row__project-title">{project.title}</h3>
                        <p className="netflix-row__description">{project.description}</p>
                        
                        <div className="netflix-row__technologies">
                          {project.technologies.slice(0, 3).map((tech) => (
                            <span
                              key={tech.id}
                              className="netflix-row__tech-badge"
                              style={{ backgroundColor: tech.color }}
                            >
                              {tech.icon && (
                                <span className="netflix-row__tech-icon">{tech.icon}</span>
                              )}
                              <span className="netflix-row__tech-name">{tech.name}</span>
                            </span>
                          ))}
                          {project.technologies.length > 3 && (
                            <span className="netflix-row__tech-more">
                              +{project.technologies.length - 3} more
                            </span>
                          )}
                        </div>

                        <div className="netflix-row__actions">
                          <button className="netflix-row__play-btn" aria-label="View project">
                            <svg viewBox="0 0 24 24" fill="currentColor">
                              <path d="M8 5v14l11-7z"/>
                            </svg>
                            View Project
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>

                  {project.featured && (
                    <div className="netflix-row__featured-badge">
                      ⭐ Featured
                    </div>
                  )}
                </div>
              </div>
            );
          })}
          
          {showContactCard && onContactClick && (
            <div className="netflix-row__item">
              <ContactCard onContactClick={onContactClick} />
            </div>
          )}
        </div>

        {canScrollRight && (
          <button
            className="netflix-row__scroll-btn netflix-row__scroll-btn--right"
            onClick={() => scroll('right')}
            aria-label="Scroll right"
          >
            <svg viewBox="0 0 24 24" fill="currentColor">
              <path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/>
            </svg>
          </button>
        )}
      </div>
    </div>
  );
};

export default NetflixProjectRow;